<span class="line"><span class="token keyword">assert</span> facility_supported<span class="token punctuation">(</span>old_tecu<span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span> <span class="token keyword">is</span> <span class="token boolean">False</span>             <span class="token comment"># 가이던스 비트는 무시</span></span>
